import{_ as o,a0 as i,w as d,s as r,ao as t,I as l,a1 as e,A as p,x as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"通过编写互动游戏学习 Bash | LCTT x X-CMD","titleTemplate":false,"description":"通过编写互动游戏学习 Bash | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通过编写互动游戏学习 Bash | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通过编写互动游戏学习 Bash | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201208 Learn Bash by writing an interactive game","title":"通过编写互动游戏学习 Bash","tag":"202012","desc":""},"relativePath":"202012/20201208 Learn Bash by writing an interactive game.md","filePath":"[post].md"}'),u={name:"202012/20201208 Learn Bash by writing an interactive game.md"};function h(m,s,g,c,b,f){const n=i("Link");return d(),r("div",null,[s[25]||(s[25]=t('<h1 id="通过编写互动游戏学习-bash" tabindex="-1">通过编写互动游戏学习 Bash <a class="header-anchor" href="#通过编写互动游戏学习-bash" aria-label="Permalink to “通过编写互动游戏学习 Bash”">​</a></h1><blockquote><p>编程一个简单的游戏是练习一门新语言并与其他你掌握的语言进行比较的好方法。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202012/28/010432yq3vgsqtiol9zzi6.jpg" alt=""></p><p>学习一门新的编程语言是很有趣的。每当我尝试学习一门新的语言时，我都会专注于定义变量、编写语句和评估表达式。一旦我对这些概念有了大致的了解，我通常可以自己弄清楚其余的概念。大多数编程语言都有一些相似之处，所以一旦你了解了一种编程语言，学习下一种编程语言就是要弄清楚其独特的细节，认识到其中的差异。</p><p>为了帮助我练习一种新的编程语言，我喜欢写一些测试程序。我经常写的一个示例程序是一个简单的“猜数字”程序，电脑在 1 到 100 之间选一个数字，让我猜这个数字。程序会一直循环，直到我猜对为止。</p><p>“猜数字”程序锻炼了编程语言中的几个概念：如何给变量赋值，如何写语句，如何进行条件判断和循环。对于学习一门新的编程语言来说，这是一个很好的实践实验。</p><h3 id="用-bash-猜数字" tabindex="-1">用 Bash 猜数字 <a class="header-anchor" href="#用-bash-猜数字" aria-label="Permalink to “用 Bash 猜数字”">​</a></h3>',7)),l("p",null,[e(n,{href:"https://en.wikipedia.org/wiki/Bash_(Unix_shell)"},{default:p(()=>[...s[0]||(s[0]=[a("Bash",-1)])]),_:1}),s[1]||(s[1]=a(" 是大多数 Linux 系统的标准 shell。除了提供丰富的命令行用户界面外，Bash 还以",-1)),s[2]||(s[2]=l("em",null,"脚本",-1)),s[3]||(s[3]=a("的形式支持完整的编程语言。",-1))]),s[26]||(s[26]=l("p",null,"如果你对 Bash 不熟悉，我推荐你看这些介绍：",-1)),l("ul",null,[l("li",null,[e(n,{href:"https://opensource.com/resources/what-bash"},{default:p(()=>[...s[4]||(s[4]=[a("什么是 Bash？",-1)])]),_:1}),s[5]||(s[5]=a("。",-1))]),l("li",null,[e(n,{href:"https://opensource.com/article/20/4/bash-programming-guide"},{default:p(()=>[...s[6]||(s[6]=[a("开始使用 Bash 编程",-1)])]),_:1})]),l("li",null,[e(n,{href:"https://opensource.com/article/20/4/bash-sysadmins-ebook"},{default:p(()=>[...s[7]||(s[7]=[a("系统管理员的 Bash 脚本入门",-1)])]),_:1})]),l("li",null,[e(n,{href:"https://opensource.com/article/20/6/bash-functions"},{default:p(()=>[...s[8]||(s[8]=[a("如何在 Bash 中编写函数",-1)])]),_:1})]),l("li",null,[e(n,{href:"https://opensource.com/tags/bash"},{default:p(()=>[...s[9]||(s[9]=[a("阅读更多关于 Bash 的信息",-1)])]),_:1})])]),s[27]||(s[27]=t(`<p>你可以通过编写一个 Bash 版本的“猜数字”游戏来探索它。这是我的实现：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>number=$(( $RANDOM % 100 + 1 ))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;Guess a number between 1 and 100&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>guess=0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>while [ &quot;0$guess&quot; -ne $number ] ; do</span></span>
<span class="line"><span>        read guess</span></span>
<span class="line"><span>        [ &quot;0$guess&quot; -lt $number ] &amp;&amp; echo &quot;Too low&quot;</span></span>
<span class="line"><span>        [ &quot;0$guess&quot; -gt $number ] &amp;&amp; echo &quot;Too high&quot;</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;That&#39;s right!&quot;</span></span>
<span class="line"><span>exit 0</span></span></code></pre></div><h3 id="拆解这个脚本" tabindex="-1">拆解这个脚本 <a class="header-anchor" href="#拆解这个脚本" aria-label="Permalink to “拆解这个脚本”">​</a></h3><p>脚本中的第一行，<code>#!/bin/bash</code> 告诉 Linux 使用 Bash shell 来运行这个脚本。每个脚本都以 <code>#!</code> 字符对（LCTT 译注：释伴）开始，这表示它是一个 shell 脚本。紧跟在<code>#!</code> 后面的是要运行的 shell。在本例中，<code>/bin/bash</code> 是指 Bash shell。</p><p>要给一个变量赋值，在变量名后面列出 <code>=</code> 号。例如，语句 <code>guess=0</code> 给 <code>guess</code> 变量分配一个零值。</p><p>你也可以使用 <code>read</code> 语句提示用户输入一个值。如果你写了 <code>read guess</code> 语句，Bash 会等待用户输入一些文本，然后把这个值存储在 <code>guess</code> 变量中。</p><p>要引用一个变量的值，在变量名前使用 <code>$</code>。所以, 在 <code>guess</code> 变量中存储了一个值后, 你可以使用 <code>$guess</code> 来检索它。</p><p>你可以使用任何你喜欢的变量名称，但是 Bash 为自己保留了一些特殊的变量名称。一个特殊的变量是 <code>RANDOM</code>，每次引用它都会产生一个很大的随机数。</p><p>如果你想在存储一个值的同时执行一个操作，你需要用特殊的括号把语句括起来。这将告诉 Bash 先执行该语句，而 <code>=</code> 则将结果值存储在变量中。要评估一个数学表达式，使用 <code>$(())</code> 围在你的语句上。双括号表示一个<em>算术表达式</em>。在我的例子中，<code>number=$(( $RANDOM % 100 + 1 ))</code> 评估表达式 <code>$RANDOM % 100 + 1</code>，然后将值存储在 <code>number</code> 变量中。</p><p>标准的算术运算符，如 <code>+</code>（加）、<code>-</code>（减）、<code>*</code>（乘）、<code>/</code>（除）和 <code>%</code>（模）都适用。</p><p>这意味着语句 <code>number=$(( $RANDOM % 100 + 1 ))</code> 产生一个 1 到 100 之间的随机数。模数运算符（<code>%</code>）返回两个数相除后的余数。在这种情况下，Bash 将一个随机数除以 100，剩下的余数范围是 0 到 99，通过在这个值上加 1，你可以得到一个介于 1 和 100 之间的随机数。</p><p>Bash 支持像循环这样的<em>条件表达式</em>和<em>流程控制</em>。在“猜数字”的游戏中，只要 <code>guess</code> 中的值不等于 <code>number</code>，Bash 就会继续循环。如果猜的数小于随机数，Bash 就会打印“太低”，如果猜的数大于数字，Bash 就会打印“太高”。</p><h3 id="它是如何工作的" tabindex="-1">它是如何工作的 <a class="header-anchor" href="#它是如何工作的" aria-label="Permalink to “它是如何工作的”">​</a></h3><p>现在你已经写好了你的 Bash 脚本，你可以运行它来玩“猜数字”游戏。一直猜，直到你找到正确的数字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Guess a number between 1 and 100</span></span>
<span class="line"><span>50</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>30</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>20</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>10</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>15</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>13</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>14</span></span>
<span class="line"><span>That&#39;s right!</span></span></code></pre></div><p>每次运行这个脚本，Bash 都会随机选择一个不同的数字。</p><p>这个“猜数字”游戏是学习新的编程语言时的一个很好的入门程序，因为它以一种很直接的方式锻炼了几个常见的编程概念。通过在不同的编程语言中实现这个简单的游戏，你可以展示一些核心概念，并比较每种语言的细节。</p><p>你有喜欢的编程语言吗？你会如何用它来写“猜数字”游戏呢？请关注本系列文章，看看你可能感兴趣的其他编程语言的例子。</p><hr>`,19)),l("p",null,[s[11]||(s[11]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/20/12/learn-bash"},{default:p(()=>[...s[10]||(s[10]=[a("https://opensource.com/article/20/12/learn-bash",-1)])]),_:1})]),l("p",null,[s[16]||(s[16]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/jim-hall"},{default:p(()=>[...s[12]||(s[12]=[a("Jim Hall",-1)])]),_:1}),s[17]||(s[17]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[13]||(s[13]=[a("lujun9972",-1)])]),_:1}),s[18]||(s[18]=a(" 译者：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1}),s[19]||(s[19]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[15]||(s[15]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[22]||(s[22]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[20]||(s[20]=[a("LCTT",-1)])]),_:1}),s[23]||(s[23]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[21]||(s[21]=[a("Linux中国",-1)])]),_:1}),s[24]||(s[24]=a(" 荣誉推出",-1))])])}const x=o(u,[["render",h]]);export{k as __pageData,x as default};
